def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge overlapping/touching intervals in a
    def merge(intervals):
        if not intervals:
            return []
        intervals.sort()
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    a_merged = merge(a)
    b_merged = merge(b)

    # For each interval in a_merged, subtract all intervals in b_merged
    result = []

    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_intervals = []
            for c_start, c_end in current_intervals:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    new_intervals.append([c_start, c_end])
                else:
                    # There is overlap, keep non-overlapping parts
                    if c_start < b_start:
                        new_intervals.append([c_start, b_start])
                    if c_end > b_end:
                        new_intervals.append([b_end, c_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge touching intervals in result
    result = merge(result)

    return result

